LIB.push(
{t:"La mappa dell'empatia",c:"lav",tg:"Cosa dice, pensa, fa e prova la persona per cui stai lavorando?",d:1,
sp:"La mappa dell'empatia è un foglio diviso in quattro riquadri che descrivono una persona: cosa dice, cosa pensa, cosa fa e cosa prova. Spesso si aggiungono le sue fatiche e i suoi desideri. Serve a mettersi davvero nei panni di un cliente, di un collega o di un familiare, invece di immaginarlo come vorremmo che fosse.",
ap:["Lo strumento, creato da Dave Gray, aiuta a notare le contraddizioni: una persona può dire una cosa e farne un'altra, o pensare cose che non dice. Proprio lì si nascondono i bisogni veri. Si compila meglio dopo aver osservato o ascoltato davvero la persona, non a tavolino.","Usala prima di progettare un servizio, preparare una presentazione o affrontare una conversazione difficile. Il rischio è riempirla con le proprie supposizioni: segna cosa hai osservato e cosa stai solo immaginando."],
ri:[["Non capisci le reazioni di qualcuno","Ti sorprende come risponde."],["Progetti per persone che non conosci","Decidi senza averle ascoltate."],["Dire e fare non coincidono","La persona dice una cosa e ne fa un'altra."]],
es:[["Lavoro","Un negozio fa la mappa dei clienti anziani: dicono che va tutto bene, ma fanno fatica a leggere i prezzi e provano imbarazzo a chiedere. Si ingrandiscono le etichette."],["Famiglia","Prima di parlare con un figlio adolescente, scrivi cosa dice, fa, pensa e prova. Scopri che la sua rabbia nasconde paura per la scuola."]],
ex:["Scegli una persona importante per un tuo progetto e compila i quattro riquadri.","Segna con due colori ciò che hai osservato e ciò che supponi.","Fai una domanda aperta a quella persona per verificare una delle tue supposizioni."],
q:["Cosa dice e cosa fa davvero questa persona?","Cosa potrebbe pensare e provare senza dirlo?","Quali sono le sue fatiche e i suoi desideri?"],
er:"Compilare la mappa con le proprie idee invece che con osservazioni reali.",
qz:[["Quali sono i riquadri classici della mappa dell'empatia?",["Costi, ricavi, rischi, tempi","Dice, pensa, fa, prova","Chi, cosa, dove, quando","Passato, presente, futuro, sogni"],1,"Descrivono la persona da quattro lati."],["Perché sono utili le contraddizioni tra dire e fare?",["Mostrano che la persona mente","Rivelano bisogni nascosti","Non sono utili","Semplificano la mappa"],1,"Lì emergono i bisogni veri."]]},

{t:"L'effetto dotazione",c:"rag",tg:"Diamo più valore a ciò che possediamo solo perché è nostro.",d:2,
sp:"L'effetto dotazione è la tendenza a valutare un oggetto di più quando lo possediamo. In un famoso esperimento di Richard Thaler e colleghi, chi riceveva una tazza chiedeva per venderla circa il doppio di quanto gli altri erano disposti a pagarla. Questo ci rende difficile vendere, buttare via, cambiare.",
ap:["L'effetto è legato all'avversione alla perdita: separarci da qualcosa ci sembra una perdita, e le perdite pesano più dei guadagni. Per questo le prove gratuite funzionano: dopo una settimana con un prodotto, ci sembra già nostro e rinunciarvi costa.","Per contrastarlo, chiediti: se non lo avessi, lo comprerei oggi a questo prezzo? Quando vendi casa o auto, informati sui prezzi reali invece di fidarti della sensazione. E quando riordini, ricorda che conservare ha un costo di spazio e attenzione."],
ri:[["Fatica a buttare","Tieni oggetti che non usi da anni."],["Prezzi di vendita troppo alti","Pensi che la tua cosa valga più del mercato."],["Prove gratuite","Dopo averlo provato, ti sembra impossibile rinunciare."]],
es:[["Casa","Vuoi vendere l'auto a 9.000 euro perché «è tenuta benissimo». Il mercato ne offre 7.000. Ti chiedi: la ricomprerei a 9.000? No."],["Acquisti","Un abbonamento gratuito per un mese diventa a pagamento. Prima della scadenza ti chiedi se lo sottoscriveresti da zero."]],
ex:["Scegli cinque oggetti che non usi da un anno e chiediti per ciascuno: lo comprerei oggi?","Prima di una vendita, cerca tre prezzi reali di oggetti simili.","Annota le prove gratuite attive e decidi in anticipo se le terrai."],
q:["Se non lo avessi, lo comprerei oggi a questo prezzo?","Sto valutando questo oggetto o il fatto che è mio?","Quanto mi costa tenerlo?"],
er:"Pensare che il valore affettivo sia valore di mercato.",
qz:[["Cosa mostra l'esperimento delle tazze?",["Le tazze valgono poco","Chi possiede un oggetto chiede di più di quanto altri pagherebbero","Tutti valutano uguale","Le persone non vendono mai"],1,"Possedere aumenta il valore percepito."],["Quale domanda aiuta a contrastare l'effetto dotazione?",["Quanto l'ho pagato?","Se non lo avessi, lo comprerei oggi a questo prezzo?","Chi me l'ha regalato?","Quanto è vecchio?"],1,"Toglie il peso del possesso."]]},

{t:"La mente estesa",c:"app",tg:"Pensiamo anche con il corpo, gli strumenti, gli spazi e le altre persone.",d:2,
sp:"I filosofi Andy Clark e David Chalmers hanno proposto che la mente non finisca dentro la testa: quaderni, calendari, ambienti, gesti e conversazioni fanno parte del nostro modo di pensare. La scrittrice Annie Murphy Paul ha mostrato come usarlo in pratica: muoverti, cambiare ambiente, scrivere e parlare con altri ti fa pensare meglio che sforzarti solo con la testa.",
ap:["Fare un calcolo difficile su carta è più facile che a mente; camminare aiuta a trovare idee; spiegare a qualcuno chiarisce i pensieri; un ambiente ordinato e con luce naturale migliora la concentrazione. Non sono aiuti esterni al pensiero: sono parte del pensiero.","Per usarlo, quando sei bloccato non insistere solo con la testa: disegna, scrivi, cammina, cambia stanza, parla con qualcuno. E costruisci intorno a te strumenti che ricordano e organizzano al posto tuo."],
ri:[["Pensieri che girano in tondo","Ripeti le stesse idee senza progredire."],["Tutto a memoria","Cerchi di tenere tutto in testa."],["Ambiente che distrae","Il luogo in cui lavori non ti aiuta."]],
es:[["Lavoro","Bloccato su un problema, esci a camminare 20 minuti con un quaderno. Rientri con due idee nuove."],["Studio","Invece di rileggere gli appunti, li spieghi ad alta voce a un amico. Capisci dove non hai capito."]],
ex:["La prossima volta che sei bloccato, disegna il problema su un foglio invece di pensarci.","Fai una passeggiata di 15 minuti con una domanda precisa in mente.","Togli dalla mente tre cose da ricordare e mettile in un calendario o in una lista."],
q:["Posso pensare meglio scrivendo, disegnando o camminando?","L'ambiente in cui sono mi aiuta o mi ostacola?","Con chi potrei pensare ad alta voce?"],
er:"Credere che pensare bene significhi solo sforzarsi di più con la testa.",
qz:[["Cosa sostiene l'idea della mente estesa?",["Il cervello è inutile","Strumenti, corpo, ambiente e altre persone fanno parte del pensiero","Bisogna memorizzare tutto","Il pensiero avviene solo in silenzio"],1,"Pensiamo anche fuori dalla testa."],["Sei bloccato su un problema. Cosa suggerisce il modello?",["Concentrarti ancora più forte","Scrivere, disegnare, camminare o parlarne con qualcuno","Rinunciare","Dormire sempre"],1,"Cambiare il modo di pensare sblocca."]]},

{t:"Pensiero veloce e lento",c:"rag",tg:"Un sistema rapido e intuitivo, uno lento e riflessivo: sappi quando usarli.",d:2,
sp:"Daniel Kahneman descrive due modi di pensare. Il Sistema 1 è veloce, automatico, intuitivo: riconosce un volto, guida su una strada nota, reagisce a un pericolo. Il Sistema 2 è lento, faticoso, ragionato: fa un calcolo difficile, confronta opzioni, controlla un ragionamento. Gran parte degli errori di giudizio nasce quando usiamo il Sistema 1 dove servirebbe il Sistema 2.",
ap:["Il Sistema 1 è prezioso: senza di lui saremmo lentissimi in tutto. Ma usa scorciatoie che in certi casi sbagliano: ancoraggio, disponibilità, effetto alone. Il Sistema 2 può correggerle, ma è pigro e si stanca facilmente, soprattutto quando siamo stanchi, affamati o di fretta.","Per usarlo, riconosci le decisioni in cui l'intuizione non basta: quelle importanti, nuove, con molti numeri o dove sei emotivamente coinvolto. Lì rallenta: scrivi, confronta, chiedi un parere, dormici sopra."],
ri:[["Risposta immediata a domande difficili","Rispondi d'istinto a qualcosa di complesso."],["Decisioni prese stanchi","Sera, fame, fretta."],["Sicurezza senza ragionamento","Senti di avere ragione ma non sai spiegare perché."]],
es:[["Soldi","Un'offerta di finanziamento ti sembra conveniente al primo sguardo. Rallenti, fai il calcolo del costo totale e scopri che non lo è."],["Lavoro","Un collega esperto riconosce subito un guasto (Sistema 1). Per decidere un investimento grande, il gruppo usa invece un'analisi scritta (Sistema 2)."]],
ex:["Prima di una decisione importante questa settimana, aspetta un giorno e scrivi i pro e i contro.","Nota tre momenti in cui hai risposto d'istinto: era la scelta giusta?","Evita le decisioni importanti la sera tardi o quando hai fame."],
q:["Questa decisione merita il pensiero lento?","Sto rispondendo d'istinto a una domanda difficile?","Sono stanco, affamato o di fretta?"],
er:"Diffidare sempre dell'intuizione: negli ambiti dove hai molta esperienza è spesso affidabile.",
qz:[["Quale attività usa soprattutto il Sistema 2?",["Riconoscere un amico","Confrontare con attenzione due offerte di mutuo","Frenare davanti a un ostacolo","Leggere un cartello"],1,"Richiede ragionamento lento e faticoso."],["Quando il Sistema 2 funziona peggio?",["Di mattina riposati","Quando siamo stanchi, affamati o di fretta","Quando scriviamo","Quando abbiamo tempo"],1,"È faticoso e si stanca facilmente."]]},

{t:"Caratteristiche e benefici",c:"com",tg:"Le persone non comprano le caratteristiche di una cosa, ma ciò che cambia nella loro vita.",d:1,
sp:"Una caratteristica descrive cosa è una cosa: «batteria da 5.000 mAh». Un beneficio descrive cosa fa per te: «arrivi a sera senza cercare una presa». Quando presenti un prodotto, un'idea o te stesso, le caratteristiche da sole lasciano freddi. Il modello ti invita a tradurre ogni caratteristica in un beneficio concreto per chi ascolta.",
ap:["Un trucco semplice è aggiungere «e questo significa che…» dopo ogni caratteristica. «Il corso dura 6 settimane, e questo significa che puoi finirlo prima delle vacanze». Il beneficio deve parlare dei bisogni di chi ascolta, non dei tuoi.","Le caratteristiche restano utili come prova: il beneficio convince, la caratteristica rende credibile. Funziona anche nei colloqui: «ho gestito un team di 5 persone» diventa «so far lavorare insieme persone diverse per rispettare le scadenze»."],
ri:[["Elenchi tecnici","Descrivi il prodotto con numeri e sigle."],["Ascoltatori distratti","Le persone non capiscono perché dovrebbe interessargli."],["Curriculum pieni di compiti","Elenchi cosa facevi, non cosa hai ottenuto."]],
es:[["Lavoro","Un idraulico scrive sul volantino: «Interventi entro 2 ore, e questo significa che non resti senza acqua calda la sera»."],["Te stesso","Nel colloquio, invece di «conosco Excel», dici «ho ridotto da due giorni a due ore il report mensile»."]],
ex:["Scegli qualcosa che offri e scrivi tre caratteristiche, poi trasformale in benefici con «e questo significa che…».","Riscrivi una riga del tuo curriculum come beneficio.","Ascolta una pubblicità e separa le caratteristiche dai benefici."],
q:["Cosa cambia concretamente per chi ascolta?","Ho tradotto ogni caratteristica in un beneficio?","Quale caratteristica rende credibile il beneficio?"],
er:"Promettere benefici vaghi («ti cambierà la vita») senza caratteristiche che li sostengono.",
qz:[["Quale frase esprime un beneficio?",["Lo zaino ha 30 litri di capienza","Lo zaino contiene tutto per un weekend senza valigia","Lo zaino è blu","Lo zaino pesa 900 grammi"],1,"Descrive cosa cambia per chi lo usa."],["Quale frase aiuta a trasformare una caratteristica in beneficio?",["«Inoltre…»","«E questo significa che…»","«Tecnicamente…»","«In sintesi…»"],1,"Collega la caratteristica alla vita di chi ascolta."]]},

{t:"Il diagramma a lisca di pesce",c:"rag",tg:"Disegna tutte le possibili cause di un problema raggruppate per categoria.",d:1,
sp:"Il diagramma di Ishikawa, chiamato a lisca di pesce per la sua forma, mette il problema nella testa del pesce e le possibili cause sulle lische, raggruppate in categorie: persone, metodi, strumenti, materiali, ambiente, misure. Serve a esplorare tutte le cause prima di scegliere su cui intervenire, invece di fermarsi alla prima che viene in mente.",
ap:["Kaoru Ishikawa lo sviluppò per il controllo della qualità nelle aziende giapponesi. Funziona bene in gruppo: ognuno aggiunge cause dalla propria esperienza, e il disegno rende visibile che un problema raramente ha una sola origine.","Dopo aver riempito le lische, scegli le cause più probabili e verificale con i fatti. Si può combinare con i cinque perché per scavare in ciascuna. Le categorie si adattano al contesto: per un problema personale possono essere tempo, energia, ambiente, persone, abitudini."],
ri:[["Problema con molte cause possibili","Non sai dove guardare."],["Discussioni sulla colpa","Ognuno indica una causa diversa."],["Soluzioni che non funzionano","Hai agito sulla causa sbagliata."]],
es:[["Lavoro","I clienti si lamentano della consegna tardiva. Il gruppo disegna le lische: personale insufficiente il lunedì, software lento, imballaggi mancanti, traffico. Interviene prima sugli imballaggi."],["Te stesso","Dormi male. Le lische: caffè (abitudini), telefono a letto (strumenti), camera calda (ambiente), preoccupazioni di lavoro (persone)."]],
ex:["Disegna una lisca di pesce per un problema ricorrente con almeno quattro categorie.","Cerchia le due cause più probabili e trova un modo per verificarle.","Fai l'esercizio con un'altra persona coinvolta nel problema."],
q:["Quali categorie di cause posso esplorare?","Quali cause sono più probabili secondo i fatti?","Mi sono fermato alla prima causa che mi è venuta in mente?"],
er:"Riempire il diagramma e poi non verificare quali cause siano reali.",
qz:[["Cosa si scrive nella testa del pesce?",["Le soluzioni","Il problema","Le persone responsabili","I costi"],1,"Le cause stanno sulle lische."],["Qual è il vantaggio principale del diagramma?",["Trova subito il colpevole","Fa esplorare molte cause prima di scegliere","Elimina il problema","È decorativo"],1,"Evita di fermarsi alla prima causa."]]},

{t:"Costi fissi e variabili",c:"eco",tg:"Alcuni costi restano uguali qualunque cosa succeda, altri crescono con quanto fai.",d:1,
sp:"I costi fissi non cambiano con la quantità prodotta o usata: affitto, abbonamento, rata dell'auto. I costi variabili crescono con l'uso: benzina, materie prime, ore pagate. Distinguerli aiuta a capire quanto rischi, quando conviene crescere e dove risparmiare.",
ap:["Un'attività con molti costi fissi ha bisogno di tanti clienti per coprirli, ma poi ogni cliente in più rende molto: è il caso di una palestra. Un'attività con costi soprattutto variabili rischia meno, ma guadagna meno da ogni cliente in più. Il punto in cui i ricavi coprono tutti i costi si chiama punto di pareggio.","Nella vita personale, i costi fissi alti rendono fragili: se perdi il reddito, devi comunque pagarli. Ridurre i costi fissi (affitto, abbonamenti, rate) dà più libertà di scegliere. Un costo fisso può anche convenire se lo usi molto: l'abbonamento ai mezzi conviene se viaggi ogni giorno."],
ri:[["Spese che non scendono mai","Anche nei mesi di poco uso paghi lo stesso."],["Abbonamenti dimenticati","Pagamenti fissi per cose che non usi."],["Crescita rischiosa","Aumentare i costi fissi per crescere."]],
es:[["Casa","Elenchi i costi fissi mensili: affitto, rata, tre abbonamenti streaming, palestra non usata. Tagli due abbonamenti e la palestra."],["Lavoro","Una piccola pasticceria invece di affittare un secondo laboratorio (costo fisso) paga un laboratorio a ore quando ci sono ordini grandi (costo variabile)."]],
ex:["Dividi le tue spese mensili in fisse e variabili.","Calcola quanto costerebbe un mese senza reddito solo per i costi fissi.","Trasforma un costo fisso poco usato in variabile o eliminalo."],
q:["Questo costo cambia con l'uso o resta uguale?","Quanto mi costano i costi fissi se il reddito si ferma?","Uso abbastanza questo servizio da giustificare un costo fisso?"],
er:"Considerare «economico» un abbonamento senza calcolare quanto lo usi davvero.",
qz:[["Quale è un costo variabile?",["L'affitto","La benzina per l'auto","La rata del mutuo","L'abbonamento annuale"],1,"Cresce con quanto usi l'auto."],["Perché costi fissi alti rendono fragili?",["Perché sono illegali","Perché vanno pagati anche quando il reddito cala","Perché scendono sempre","Non rendono fragili"],1,"Non si adattano ai periodi difficili."]]},

{t:"Pensiero focalizzato e diffuso",c:"app",tg:"Alterna concentrazione intensa e pause rilassate: il cervello impara in entrambi i modi.",d:2,
sp:"Barbara Oakley, ingegnera e insegnante, descrive due modi di lavorare del cervello. Il modo focalizzato è concentrato su un problema preciso, come una torcia puntata. Il modo diffuso si attiva quando ci rilassiamo, camminiamo, facciamo la doccia: il cervello fa collegamenti più ampi, come una luce che illumina tutta la stanza. Per imparare e creare servono entrambi.",
ap:["Molte intuizioni arrivano quando smettiamo di pensarci: sotto la doccia, in passeggiata, prima di dormire. Ma arrivano solo se prima ci siamo concentrati sul problema. Il modo diffuso lavora sul materiale raccolto dal modo focalizzato.","Per usarlo, lavora concentrato su un problema difficile per un periodo, poi fai una pausa vera: cammina, fai sport, dormi. Non riempire la pausa con il telefono, che tiene la mente focalizzata su altro. Quando torni, spesso la soluzione è più vicina."],
ri:[["Bloccato da ore","Più ti sforzi, meno trovi."],["Idee sotto la doccia","Le soluzioni arrivano nei momenti di pausa."],["Pause sul telefono","Non lasci mai la mente libera."]],
es:[["Studio","Uno studente non capisce un esercizio di matematica. Studia 40 minuti, poi va a correre. Riprovando, lo risolve in dieci minuti."],["Lavoro","Una designer bloccata su un logo lo lascia e va a fare la spesa a piedi. Durante la camminata le viene l'idea."]],
ex:["Su un problema difficile, lavora concentrato 30 minuti e poi fai una passeggiata senza telefono.","Tieni un quaderno vicino al letto o in borsa per le idee che arrivano nei momenti diffusi.","Per una settimana, sostituisci una pausa sul telefono con una pausa senza schermi."],
q:["Mi sono concentrato abbastanza prima di fare una pausa?","La mia pausa lascia la mente libera?","Sto insistendo troppo invece di lasciar lavorare il modo diffuso?"],
er:"Usare il modo diffuso come scusa per non concentrarsi mai.",
qz:[["Quando si attiva il modo diffuso?",["Durante la concentrazione intensa","Quando ci rilassiamo, camminiamo o dormiamo","Solo di notte","Mai"],1,"La mente fa collegamenti ampi a riposo."],["Perché il telefono rovina la pausa?",["Consuma batteria","Tiene la mente focalizzata su altro","È rumoroso","Non la rovina"],1,"Non lascia spazio al modo diffuso."]]},

{t:"Framestorming: cambiare la domanda",c:"rag",tg:"Prima di cercare risposte, cerca la domanda giusta.",d:2,
sp:"Il brainstorming genera molte risposte a una domanda. Il framestorming, proposto dalla ricercatrice Tina Seelig, genera molte domande diverse sullo stesso problema. Il modo in cui formuli il problema decide quali soluzioni riesci a vedere: cambiando la domanda, cambiano le risposte possibili.",
ap:["Chiedersi «come organizzo una festa di compleanno?» porta a soluzioni classiche. Chiedersi «come faccio sentire speciale mia figlia?» oppure «come creo un ricordo per tutta la famiglia?» apre strade completamente diverse. Spesso il problema è che stiamo rispondendo bene alla domanda sbagliata.","Per farlo, scrivi il problema come domanda, poi riscrivilo in almeno dieci modi: più ampio, più ristretto, dal punto di vista di un'altra persona, al contrario, togliendo un vincolo. Scegli la domanda che apre le possibilità più interessanti."],
ri:[["Soluzioni tutte simili","Il brainstorming produce variazioni della stessa idea."],["Problema dato per scontato","Nessuno si chiede se la domanda sia giusta."],["Bloccato","Nessuna risposta ti convince."]],
es:[["Lavoro","Invece di «come facciamo a vendere più ombrelli?», il gruppo si chiede «come aiutiamo le persone a non bagnarsi in città?». Nasce un servizio di noleggio ombrelli."],["Casa","Invece di «come convinco mio figlio a leggere?», ti chiedi «cosa ama raccontare mio figlio?». Scopri i fumetti."]],
ex:["Scrivi un problema attuale come domanda e riscrivilo in dieci modi diversi.","Riformula il problema dal punto di vista di un'altra persona coinvolta.","Togli un vincolo dalla domanda (tempo, soldi) e osserva quali idee nascono."],
q:["Sto rispondendo alla domanda giusta?","Come la riformulerebbe un'altra persona?","Quale versione della domanda apre più possibilità?"],
er:"Passare tutto il tempo a riformulare senza mai scegliere e agire.",
qz:[["Cosa genera il framestorming?",["Molte risposte","Molte domande diverse sullo stesso problema","Un piano","Un budget"],1,"Lavora sulla formulazione del problema."],["Perché cambiare la domanda può aiutare?",["Perché le risposte dipendono da come è posto il problema","Perché è più veloce","Per confondere il gruppo","Non aiuta"],0,"La domanda delimita le soluzioni visibili."]]},

{t:"Fissità funzionale",c:"rag",tg:"Vediamo gli oggetti solo per l'uso abituale e non notiamo altri usi possibili.",d:2,
sp:"La fissità funzionale è la tendenza a vedere un oggetto solo per la funzione a cui siamo abituati. Nel famoso problema della candela di Karl Duncker, le persone dovevano fissare una candela al muro con una scatola di puntine e dei fiammiferi. Pochi pensavano di svuotare la scatola e usarla come supporto. Il modello ti invita a guardare oggetti, competenze e risorse con occhi nuovi.",
ap:["La fissità colpisce anche le idee e le persone: pensiamo che un collega sappia fare solo il suo lavoro, che una stanza serva solo a una cosa, che una competenza valga solo in un settore. Le soluzioni creative spesso nascono usando qualcosa in modo diverso.","Per superarla, descrivi gli oggetti in modo generico invece che con il loro nome: non «una scatola di puntine», ma «un contenitore di cartone». Chiediti: cos'altro potrebbe fare? Come lo userebbe un bambino o qualcuno di un altro Paese?"],
ri:[["«Non ho ciò che mi serve»","Pensi che manchi uno strumento."],["Risorse sottoutilizzate","Spazi, oggetti o competenze usati solo in un modo."],["Ruoli rigidi","Ognuno fa solo ciò che ha sempre fatto."]],
es:[["Casa","Ti serve un leggio per una ricetta. Usi una gruccia da pantaloni appesa al pensile."],["Lavoro","Un'impiegata dell'amministrazione disegna benissimo. Il capo le chiede di illustrare le istruzioni per i clienti, che diventano molto più chiare."]],
ex:["Scegli un oggetto di casa e trova cinque usi diversi da quello abituale.","Descrivi un problema usando parole generiche per gli strumenti che hai.","Pensa a una persona che conosci e a una sua capacità che nessuno usa."],
q:["Cos'altro potrebbe fare questo oggetto o questa risorsa?","Come lo descriverei senza usare il suo nome?","Quale competenza nascosta potrei valorizzare?"],
er:"Credere che servano sempre strumenti nuovi per risolvere un problema.",
qz:[["Nel problema della candela, qual era la soluzione?",["Usare più fiammiferi","Svuotare la scatola e usarla come supporto","Sciogliere la candela","Chiedere aiuto"],1,"La scatola andava vista come supporto, non solo contenitore."],["Come superare la fissità funzionale?",["Comprare nuovi strumenti","Descrivere gli oggetti in modo generico e chiedersi altri usi","Fare come sempre","Aspettare"],1,"Il linguaggio generico apre nuove funzioni."]]},

{t:"La matrice GE-McKinsey",c:"eco",tg:"Confronta attività secondo quanto è attraente il mercato e quanto sei forte tu.",d:3,
sp:"La matrice GE-McKinsey, sviluppata negli anni Settanta per General Electric, aiuta a decidere dove investire. Ogni attività viene valutata su due assi, ciascuno diviso in alto, medio e basso: quanto è attraente il settore (dimensione, crescita, margini, rischi) e quanto è forte la tua posizione (quota, competenze, marchio). Le nove caselle indicano se investire, mantenere o ridurre.",
ap:["Rispetto alla matrice BCG, che usa solo crescita del mercato e quota, questa considera molti fattori e li pesa. È più completa ma richiede più giudizio. Le attività in alto a destra (settore attraente, posizione forte) meritano investimenti; quelle in basso a sinistra vanno ridotte o abbandonate.","Puoi usarla in versione semplice per scelte personali: tra più progetti o corsi di studio, valuta quanto è promettente il campo e quanto sei forte tu. Ricorda che i punteggi sono stime: discutili con altri."],
ri:[["Tante attività, risorse limitate","Devi scegliere dove investire."],["Settori in cambiamento","Alcune aree diventano più o meno attraenti."],["Scelte basate su un solo criterio","Guardi solo la crescita o solo la tua bravura."]],
es:[["Lavoro","Un'agenzia valuta tre servizi: siti web (mercato affollato, posizione media), video (mercato in crescita, posizione forte), stampa (mercato in calo, posizione debole). Investe nei video."],["Te stesso","Scegliendo una specializzazione, valuti quanto è richiesto ogni campo e quanto sei portato. Scegli quello alto in entrambi."]],
ex:["Elenca tre progetti o attività e dai a ciascuno un voto da 1 a 3 per attrattività del settore e per tua forza.","Posizionali nelle nove caselle e decidi dove investire.","Chiedi a una persona esterna di dare i suoi voti e confrontali."],
q:["Quanto è attraente questo campo, oggi e domani?","Quanto sono forte io rispetto agli altri?","Dove le risorse renderebbero di più?"],
er:"Dare voti precisi a fattori incerti e prenderli come verità.",
qz:[["Quali sono i due assi della matrice GE-McKinsey?",["Costi e ricavi","Attrattività del settore e forza della posizione","Tempo e denaro","Clienti e fornitori"],1,"Sono valutati con più fattori ciascuno."],["Cosa fare con un'attività in un settore poco attraente e posizione debole?",["Investire di più","Ridurla o abbandonarla","Ignorarla","Raddoppiarla"],1,"È la zona meno promettente."]]},

{t:"Getting Things Done",c:"app",tg:"Togli dalla testa tutti gli impegni e mettili in un sistema affidabile.",d:2,
sp:"David Allen ha creato il metodo GTD partendo da un'idea: la mente serve ad avere idee, non a ricordare cose. Ogni impegno aperto che tieni a mente ti toglie energia. Il metodo ha cinque passi: raccogli tutto, chiarisci cosa significa e qual è la prossima azione, organizza in liste, rivedi ogni settimana, agisci.",
ap:["Il cuore del metodo è la prossima azione: invece di «organizzare le vacanze», scrivi «chiamare Marco per le date». Un compito vago blocca, un'azione concreta si fa. Se un'azione richiede meno di due minuti, falla subito.","La revisione settimanale è ciò che rende il sistema affidabile: senza, le liste invecchiano e la mente torna a ricordare tutto da sola. Non servono app speciali: un quaderno funziona, purché sia l'unico posto dove raccogli tutto."],
ri:[["Mente affollata","Pensi continuamente alle cose da fare."],["Liste vaghe","Compiti come «sistemare la casa»."],["Promemoria sparsi","Biglietti, messaggi e note in posti diversi."]],
es:[["Casa","Raccogli in un quaderno tutte le cose in sospeso: sono 43. Per ognuna scrivi la prossima azione. La sera ti senti più leggero."],["Lavoro","Ogni venerdì dedichi 30 minuti alla revisione delle liste. Il lunedì sai già da dove iniziare."]],
ex:["Scrivi su un foglio tutto ciò che hai in sospeso, senza filtri.","Per ogni voce, scrivi la prossima azione concreta.","Fissa in agenda una revisione settimanale di 20 minuti."],
q:["Qual è la prossima azione concreta?","Ci vogliono meno di due minuti? Allora la faccio subito.","Il mio sistema contiene davvero tutto?"],
er:"Passare più tempo a organizzare le liste che a fare le cose.",
qz:[["Cos'è la «prossima azione» nel GTD?",["Il progetto completo","Il primo passo fisico e concreto da fare","Una scadenza","Un obiettivo annuale"],1,"Rende il compito eseguibile."],["Cosa rende affidabile il sistema GTD?",["Un'app costosa","La revisione settimanale","La memoria","Fare tutto subito"],1,"Senza revisione le liste perdono valore."]]},

{t:"L'effetto gradiente dell'obiettivo",c:"app",tg:"Più ci avviciniamo al traguardo, più acceleriamo.",d:1,
sp:"Lo psicologo Clark Hull osservò che i topi correvano più veloci man mano che si avvicinavano al cibo. Anche le persone si comportano così: una tessera fedeltà con due timbri già regalati viene completata prima di una vuota, anche se servono gli stessi acquisti. Il modello ti aiuta a usare la vicinanza del traguardo per motivare te stesso e gli altri.",
ap:["Gli studi di Ran Kivetz e colleghi su una caffetteria mostrarono che i clienti compravano più spesso il caffè quando mancavano pochi timbri al premio. La sensazione di progresso è un potente motore. Il rischio opposto è la fase centrale, dove l'inizio è lontano e la fine non si vede, e la motivazione cala.","Per usarlo, dividi gli obiettivi lunghi in tappe brevi, rendi visibile il progresso (barre, caselle da spuntare) e, se possibile, parti con un piccolo vantaggio già acquisito. Dopo il traguardo spesso c'è un calo: prepara il prossimo obiettivo."],
ri:[["Spinta finale","Negli ultimi giorni fai molto più che a metà."],["Calo a metà percorso","La motivazione si spegne nel mezzo."],["Progresso invisibile","Non sai quanto manca."]],
es:[["Salute","Vuoi camminare 100 km in un mese. Usi una tabella con 20 caselle da 5 km. Più caselle colori, più cammini."],["Lavoro","Un responsabile divide un progetto di sei mesi in sei traguardi mensili. La motivazione resta alta."]],
ex:["Dividi un obiettivo lungo in tappe brevi e disegna una barra o caselle per segnare il progresso.","Trova un modo per partire con un piccolo vantaggio già fatto.","Prepara in anticipo il prossimo obiettivo per evitare il calo dopo il traguardo."],
q:["Quanto manca al traguardo, ed è visibile?","Come rendo più vicina la prossima tappa?","Cosa farò subito dopo il traguardo?"],
er:"Fissare un solo traguardo lontanissimo senza tappe intermedie.",
qz:[["Cosa descrive l'effetto gradiente dell'obiettivo?",["Rallentare vicino al traguardo","Aumentare lo sforzo avvicinandosi al traguardo","Non cambiare velocità","Rinunciare a metà"],1,"La vicinanza al premio aumenta la motivazione."],["Perché una tessera con due timbri regalati viene completata prima?",["Costa meno","Dà la sensazione di essere già più vicini al traguardo","È più bella","Per caso"],1,"Il progresso percepito accelera lo sforzo."]]},

{t:"La legge di Goodhart",c:"sis",tg:"Quando una misura diventa un obiettivo, smette di essere una buona misura.",d:2,
sp:"L'economista Charles Goodhart notò che quando un indicatore viene usato come obiettivo da raggiungere, le persone trovano il modo di migliorare il numero senza migliorare ciò che il numero doveva misurare. Le scuole insegnano a superare i test invece di insegnare la materia; i call center chiudono le chiamate in fretta per abbassare la durata media, lasciando i clienti insoddisfatti.",
ap:["Un indicatore è utile perché è collegato a qualcosa che conta. Ma quando le persone vengono premiate o punite in base a quel numero, cercano la strada più facile per spostarlo, e il collegamento si spezza. Un esempio storico racconta di premi per ogni cobra ucciso che portarono le persone ad allevare cobra.","Per difendersi: usa più indicatori insieme, ricorda sempre lo scopo dietro il numero, cambia gli indicatori nel tempo e chiediti come potrebbero essere aggirati. Anche nella vita personale: i passi giornalieri non sono la salute, i follower non sono l'amicizia."],
ri:[["Numeri che migliorano, realtà che no","L'indicatore sale ma il problema resta."],["Comportamenti strani","Le persone fanno cose assurde per raggiungere un obiettivo numerico."],["Obsessione per un solo dato","Tutto ruota attorno a un indicatore."]],
es:[["Lavoro","Un ospedale premia la riduzione dei tempi di attesa al pronto soccorso. I pazienti vengono «presi in carico» velocemente ma poi aspettano in corridoio."],["Te stesso","Ti fissi sui 10.000 passi e cammini avanti e indietro in casa la sera. Cambi obiettivo: 30 minuti all'aperto."]],
ex:["Scegli un numero che usi come obiettivo e scrivi lo scopo vero che dovrebbe misurare.","Chiediti come qualcuno potrebbe migliorare quel numero senza migliorare lo scopo.","Aggiungi un secondo indicatore che bilanci il primo."],
q:["Qual è lo scopo dietro questo numero?","Come si potrebbe migliorare il numero senza migliorare la realtà?","Quale altro indicatore lo bilancia?"],
er:"Rinunciare a misurare: le misure servono, ma vanno usate con giudizio.",
qz:[["Cosa dice la legge di Goodhart?",["I numeri sono sempre affidabili","Quando una misura diventa un obiettivo, smette di essere una buona misura","Bisogna misurare tutto","Le misure sono inutili"],1,"Le persone ottimizzano il numero invece dello scopo."],["Come ridurre l'effetto di Goodhart?",["Usare un solo indicatore","Usare più indicatori e ricordare lo scopo","Premiare di più","Non dire a nessuno gli obiettivi"],1,"Indicatori bilanciati sono più difficili da aggirare."]]},

{t:"Il modello GROW",c:"app",tg:"Obiettivo, realtà, opzioni, volontà: quattro domande per guidare una conversazione di crescita.",d:1,
sp:"Il modello GROW, reso popolare da John Whitmore, è una traccia per le conversazioni di coaching, anche con te stesso. Si parte dall'Obiettivo (Goal: cosa voglio ottenere), si guarda la Realtà (dove sono ora), si esplorano le Opzioni (cosa potrei fare) e si conclude con la Volontà (Will: cosa farò, quando). Aiuta a passare dalle lamentele a un piano concreto.",
ap:["La forza del modello è nelle domande, non nei consigli: chi guida la conversazione aiuta l'altro a trovare le proprie soluzioni, che sono più motivanti di quelle imposte. Ogni fase ha domande tipiche: «Cosa vuoi esattamente?», «Cosa hai già provato?», «Cos'altro potresti fare?», «Qual è il primo passo e quando?».","Puoi usarlo per aiutare un amico, un figlio, un collega, o per riflettere da solo su un quaderno. Spesso conviene tornare indietro: guardando la realtà, l'obiettivo può cambiare."],
ri:[["Conversazioni che girano in tondo","Ci si lamenta senza arrivare a nulla."],["Consigli non richiesti","Si danno soluzioni invece di aiutare a trovarle."],["Obiettivi senza piano","Sai cosa vuoi ma non cosa fare domani."]],
es:[["Lavoro","Un collega si lamenta del carico di lavoro. Gli chiedi cosa vorrebbe, cosa succede ora, quali opzioni vede. Decide di parlare con il capo giovedì."],["Te stesso","Sul quaderno: obiettivo correre 5 km; realtà ne corro 2; opzioni corsa-camminata, gruppo, app; volontà tre uscite a settimana da lunedì."]],
ex:["Applica le quattro fasi per iscritto a un tuo obiettivo.","Nella prossima conversazione in cui qualcuno ti chiede aiuto, fai solo domande GROW per 10 minuti.","Scrivi tre domande per ciascuna fase da tenere a portata di mano."],
q:["Cosa voglio ottenere esattamente?","Dove sono adesso, e cosa ho già provato?","Quali opzioni ho, e cosa farò per primo, quando?"],
er:"Saltare la fase della realtà e passare subito alle soluzioni.",
qz:[["Cosa significa la W di GROW?",["Lavoro","Volontà: cosa farò e quando","Ricchezza","Saggezza"],1,"Chiude la conversazione con un impegno."],["Qual è lo stile del modello GROW?",["Dare consigli","Fare domande che aiutano l'altro a trovare soluzioni","Giudicare","Decidere al posto dell'altro"],1,"Le soluzioni trovate da sé motivano di più."]]},

{t:"Il ciclo dell'abitudine",c:"app",tg:"Segnale, routine, ricompensa: per cambiare un'abitudine, cambia la routine.",d:1,
sp:"Charles Duhigg descrive ogni abitudine come un ciclo in tre parti: un segnale (un luogo, un'ora, un'emozione) che fa partire una routine (il comportamento) che porta a una ricompensa (il beneficio che il cervello cerca). Con il tempo il cervello collega segnale e ricompensa e la routine diventa automatica. James Clear aggiunge una quarta parte: il desiderio.",
ap:["Le abitudini non si cancellano facilmente, ma si possono modificare: mantieni lo stesso segnale e la stessa ricompensa e cambia la routine. Se alle 16 ti viene voglia di un dolce, forse la ricompensa vera è una pausa o una chiacchierata: puoi ottenerla con un caffè con un collega.","Per costruire una nuova abitudine, scegli un segnale chiaro, una routine facile e una ricompensa immediata. Per eliminarne una, rendi il segnale invisibile e la routine difficile."],
ri:[["Comportamenti automatici","Lo fai senza decidere."],["Stessa ora, stesso gesto","Ogni sera alle 22 apri il frigo."],["Voglie legate a emozioni","Stress, noia, stanchezza."]],
es:[["Salute","Ogni sera davanti alla TV mangi patatine (segnale: divano; ricompensa: relax). Tieni sul tavolino una tisana e frutta secca."],["Lavoro","Appena apri il computer controlli i social. Cambi la routine: prima scrivi le tre cose da fare oggi."]],
ex:["Scegli un'abitudine che vuoi cambiare e scrivi il suo segnale, la routine e la ricompensa.","Prova per una settimana una routine diversa con lo stesso segnale e la stessa ricompensa.","Per una nuova abitudine, scegli un segnale preciso (dopo il caffè, alle 7, uscendo dal lavoro)."],
q:["Cosa fa partire questa abitudine?","Quale ricompensa cerco davvero?","Quale routine diversa mi darebbe la stessa ricompensa?"],
er:"Cercare di eliminare un'abitudine con la sola forza di volontà senza cambiare il ciclo.",
qz:[["Quali sono le tre parti del ciclo dell'abitudine?",["Inizio, metà, fine","Segnale, routine, ricompensa","Obiettivo, piano, risultato","Pensiero, parola, azione"],1,"Il segnale avvia la routine che porta alla ricompensa."],["Qual è il modo più efficace per cambiare un'abitudine?",["Eliminare il segnale con la forza","Mantenere segnale e ricompensa e cambiare la routine","Ignorarla","Punirsi"],1,"Il cervello ottiene comunque la ricompensa che cerca."]]},

{t:"L'effetto alone",c:"rag",tg:"Una qualità che ci colpisce colora il giudizio su tutto il resto.",d:2,
sp:"L'effetto alone è la tendenza a lasciare che un'impressione positiva in un'area influenzi il giudizio su aree diverse. Una persona bella ci sembra anche più intelligente e onesta; un'azienda famosa ci sembra competente in tutto. Funziona anche al contrario: un difetto evidente fa sembrare peggiori tutte le altre qualità. Lo psicologo Edward Thorndike lo osservò negli anni Venti.",
ap:["Thorndike notò che gli ufficiali valutavano i soldati in modo uniforme: se uno sembrava bravo nell'aspetto, veniva giudicato bravo anche in disciplina e intelligenza. Oggi l'effetto agisce nei colloqui, nelle valutazioni scolastiche, nelle scelte di acquisto e nella politica.","Per ridurlo, valuta le qualità separatamente e con criteri precisi, prima di formarti un'idea complessiva. Nei colloqui usa le stesse domande per tutti e dai un voto a ciascuna risposta. Chiediti: cosa so davvero di questa persona o prodotto in quest'area specifica?"],
ri:[["Prima impressione decisiva","Un dettaglio iniziale determina tutto il giudizio."],["Esperti in tutto","Una persona famosa in un campo viene ascoltata su tutto."],["Marchi che rassicurano","Un nome noto fa sembrare migliore qualsiasi prodotto."]],
es:[["Lavoro","Un candidato è molto simpatico e ti sembra bravo in tutto. Usi una griglia di valutazione: scopri che le sue competenze tecniche sono deboli."],["Acquisti","Un attore famoso pubblicizza un'assicurazione. Ti chiedi: cosa sa lui di assicurazioni?"]],
ex:["Nella prossima valutazione di una persona o prodotto, scrivi un voto separato per ogni aspetto prima del giudizio generale.","Pensa a qualcuno che ammiri: in quali aree non hai prove della sua competenza?","Nota una pubblicità che usa un volto noto per convincerti."],
q:["Questa impressione positiva riguarda davvero l'aspetto che sto valutando?","Cosa so con certezza in quest'area specifica?","Valuterei allo stesso modo senza quel dettaglio?"],
er:"Credere di giudicare in modo oggettivo solo perché si è in buona fede.",
qz:[["Cos'è l'effetto alone?",["Un fenomeno ottico","Una qualità che influenza il giudizio su qualità diverse","Ricordare solo il negativo","Un tipo di luce"],1,"Un'impressione si estende ad altre aree."],["Come ridurre l'effetto alone in un colloquio?",["Fidarsi della prima impressione","Valutare ogni aspetto separatamente con criteri uguali per tutti","Fare colloqui più brevi","Assumere chi è più simpatico"],1,"Criteri separati limitano la contaminazione."]]},

{t:"Piacere presente e significato futuro",c:"app",tg:"La felicità duratura unisce ciò che ci piace oggi a ciò che ci serve domani.",d:2,
sp:"Tal Ben-Shahar, docente di psicologia positiva, usa l'immagine di quattro hamburger. L'hamburger spazzatura dà piacere ora e danni dopo (edonismo). Quello vegetariano insapore dà benefici futuri ma nessun piacere ora (la corsa al successo). Quello cattivo e dannoso non dà né l'uno né l'altro (rassegnazione). L'ideale è gustoso e sano: piacere presente e beneficio futuro insieme.",
ap:["Molte persone vivono rimandando sempre la felicità («sarò contento quando…») oppure inseguendo solo il piacere immediato. Entrambe le strade deludono. La felicità più stabile nasce da attività che ci piacciono e che hanno anche un significato o un beneficio nel tempo.","Per usarlo, classifica le tue attività nei quattro tipi. Cerca di aumentare quelle che uniscono piacere e significato, e trasforma le altre: rendi più piacevole ciò che è utile (studiare con un amico) e più utile ciò che è piacevole (sport che ami)."],
ri:[["«Sarò felice quando…»","Rimandi sempre la soddisfazione."],["Piaceri che lasciano vuoto","Divertimenti che poi rimpiangi."],["Senso di inutilità","Nulla ti piace né ti sembra utile."]],
es:[["Lavoro","Un'impiegata odia il lavoro ma lo sopporta pensando alla pensione. Trova un progetto interno che le piace e che la fa crescere."],["Salute","Invece di forzarti in palestra, scegli di ballare due volte a settimana: ti diverte e ti tiene in forma."]],
ex:["Elenca dieci attività della tua settimana e assegnale ai quattro tipi di hamburger.","Scegli un'attività utile ma noiosa e trova un modo per renderla piacevole.","Aggiungi alla settimana un'attività che ti dà piacere e significato insieme."],
q:["Questa attività mi dà piacere ora, beneficio dopo, o entrambi?","Sto rimandando troppo la felicità?","Come posso unire piacere e significato?"],
er:"Pensare che ogni momento debba essere sia piacevole sia utile: a volte serve sacrificio.",
qz:[["Cosa rappresenta l'hamburger «gustoso e sano»?",["Solo piacere","Piacere presente e beneficio futuro insieme","Solo sacrificio","Nessun beneficio"],1,"È il modello della felicità duratura."],["Chi vive solo per il successo futuro rinunciando a ogni piacere è...",["Edonista","Nella corsa al successo","Felice","Rassegnato"],1,"Sacrifica il presente per un futuro sempre rimandato."]]},

{t:"Il viaggio dell'eroe",c:"com",tg:"Molte storie seguono lo stesso schema: partenza, prove, trasformazione, ritorno.",d:2,
sp:"Lo studioso Joseph Campbell ha notato che miti e racconti di culture diverse seguono uno schema simile: un eroe lascia il mondo ordinario, riceve una chiamata all'avventura, incontra un mentore, affronta prove sempre più difficili, vive una crisi, si trasforma e torna a casa con un dono. Il modello aiuta a raccontare storie coinvolgenti e a leggere i cambiamenti della propria vita.",
ap:["Lo schema è stato usato consapevolmente da molti film famosi. Funziona perché rispecchia come viviamo il cambiamento: paura iniziale, aiuto di qualcuno, ostacoli, un momento buio, una nuova versione di noi. Christopher Vogler lo ha semplificato in dodici tappe per gli sceneggiatori.","Puoi usarlo per presentare un progetto (il cliente è l'eroe, tu sei il mentore), per scrivere un discorso o per guardare un momento difficile della tua vita come una fase del viaggio, non come la fine."],
ri:[["Cambiamenti importanti","Nuovo lavoro, trasloco, malattia, perdita."],["Racconti piatti","Una storia senza prove né trasformazione."],["Momenti di crisi","Ti sembra che tutto vada storto."]],
es:[["Lavoro","Nella presentazione di un prodotto, il cliente è l'eroe con un problema, l'azienda è il mentore che gli dà uno strumento, il finale mostra il cliente trasformato."],["Te stesso","Dopo un licenziamento, rileggi il periodo come la «prova» del tuo viaggio: cosa stai imparando e quale dono riporterai?"]],
ex:["Racconta un periodo difficile della tua vita seguendo le tappe: chiamata, mentore, prove, crisi, ritorno.","In una tua presentazione, fai del pubblico l'eroe e di te il mentore.","Guarda un film e riconosci le tappe del viaggio."],
q:["In quale tappa del viaggio mi trovo?","Chi è il mio mentore, e chi posso aiutare come mentore?","Quale dono porterò indietro da questa esperienza?"],
er:"Applicare lo schema in modo meccanico a ogni storia, rendendola prevedibile.",
qz:[["Chi ha descritto il viaggio dell'eroe?",["Aristotele","Joseph Campbell","Shakespeare","Freud"],1,"Lo ha descritto confrontando miti di tutto il mondo."],["In una presentazione di vendita, chi conviene rendere l'eroe?",["L'azienda","Il cliente","Il concorrente","Il prodotto"],1,"L'azienda è il mentore che aiuta l'eroe."]]},

{t:"Decisioni rapide e correggibili",c:"rag",tg:"Se una decisione si può annullare, prendila in fretta; se no, prenditi tempo.",d:1,
sp:"Jeff Bezos distingue due tipi di decisioni: le porte a senso unico, irreversibili o molto costose da annullare, e le porte a doppio senso, che si possono correggere se vanno male. Le prime meritano tempo, dati e riflessione. Le seconde vanno prese in fretta, anche con il 70% delle informazioni, perché aspettare costa più di sbagliare.",
ap:["Molte persone e organizzazioni trattano tutte le decisioni come irreversibili, con lunghe discussioni anche per scelte banali. Risultato: lentezza, occasioni perse e meno esperienza. Altri fanno l'errore opposto e prendono in fretta decisioni senza ritorno.","Prima di decidere chiediti: se sbaglio, posso tornare indietro? Quanto costa? Se la risposta è «sì, facilmente», decidi e impara dal risultato. Se è «no», rallenta, raccogli dati, chiedi pareri. Puoi anche trasformare una decisione irreversibile in una reversibile: una prova, un periodo di affitto prima di comprare."],
ri:[["Discussioni infinite su scelte piccole","Ci vuole una settimana per scegliere un fornitore di caffè."],["Decisioni irreversibili prese di corsa","Un acquisto importante deciso d'impulso."],["Paura di sbagliare","Rimandi perché non sei sicuro al 100%."]],
es:[["Casa","Indeciso tra due colori per la parete, scegli in cinque minuti: si può ridipingere. Per comprare casa invece ti prendi mesi."],["Lavoro","Un gruppo prova per un mese un nuovo orario delle riunioni invece di discuterne per settimane."]],
ex:["Elenca le decisioni in sospeso e segna quali sono reversibili.","Prendi oggi una decisione reversibile che stai rimandando.","Trasforma una decisione irreversibile in una prova temporanea."],
q:["Se sbaglio, posso tornare indietro facilmente?","Quanto mi costa aspettare?","Posso trasformare questa scelta in una prova?"],
er:"Trattare come reversibile una decisione che in realtà ha conseguenze durature.",
qz:[["Come trattare una decisione reversibile?",["Con mesi di analisi","Prendendola in fretta e imparando dal risultato","Non prendendola","Delegandola sempre"],1,"Aspettare costa più che sbagliare."],["Quale è una porta a senso unico?",["Scegliere il ristorante per stasera","Vendere l'azienda di famiglia","Provare un nuovo orario","Cambiare colore a una tazza"],1,"È molto difficile da annullare."]]},

{t:"Combinare idee lontane",c:"com",tg:"Le idee nuove nascono spesso unendo cose che sembrano non c'entrare nulla tra loro.",d:2,
sp:"Molte innovazioni sono combinazioni: Gutenberg unì la pressa per il vino ai caratteri mobili, il trolley unì una valigia a delle ruote. Più le idee combinate sono lontane, più il risultato può essere originale. Il modello ti invita a nutrirti di esperienze diverse e a cercare collegamenti tra campi distanti.",
ap:["Il pubblicitario James Webb Young diceva che un'idea non è altro che una nuova combinazione di elementi vecchi. Chi ha interessi vari ha più elementi da combinare. Per questo molte scoperte nascono ai confini tra discipline e da persone che hanno cambiato campo.","Per allenarti, leggi e frequenta ambiti lontani dal tuo, tieni un quaderno di idee, e prova a chiederti: come risolverebbe questo problema un cuoco, un giardiniere, un medico? Prendi una soluzione da un campo e trasportala nel tuo."],
ri:[["Idee sempre uguali","Le tue soluzioni assomigliano a quelle di tutti."],["Interessi molto stretti","Leggi e frequenti solo il tuo settore."],["Problema bloccato","Nessuna soluzione dal tuo campo funziona."]],
es:[["Lavoro","Un'insegnante prende l'idea dei livelli dei videogiochi e la applica agli esercizi di grammatica. I ragazzi si impegnano di più."],["Casa","Ispirandoti ai cartellini dei negozi, metti etichette ai contenitori della dispensa. La famiglia trova tutto."]],
ex:["Scegli un problema e chiediti come lo risolverebbero tre professioni lontane dalla tua.","Questa settimana leggi o guarda qualcosa su un tema che non conosci affatto.","Prendi due oggetti a caso nella stanza e inventa un prodotto che li unisce."],
q:["Quale campo lontano ha già risolto un problema simile?","Cosa succede se unisco queste due idee?","Sto nutrendo la mente con esperienze varie?"],
er:"Combinare cose a caso senza verificare se il risultato risolve un problema reale.",
qz:[["Da dove nascono spesso le idee nuove secondo il modello?",["Dal nulla","Dalla combinazione di elementi esistenti, anche lontani","Solo dagli esperti","Dal caso"],1,"Le combinazioni insolite creano novità."],["Come aumentare la capacità di combinare idee?",["Specializzarsi solo nel proprio campo","Esporsi a esperienze e conoscenze diverse","Evitare di leggere","Copiare i concorrenti"],1,"Più elementi diversi, più combinazioni possibili."]]},

{t:"L'effetto IKEA",c:"rag",tg:"Diamo più valore alle cose che abbiamo costruito noi, anche se imperfette.",d:1,
sp:"Michael Norton, Daniel Mochon e Dan Ariely hanno scoperto che le persone valutano di più gli oggetti che hanno montato con le proprie mani, come i mobili IKEA o gli origami, rispetto a oggetti identici fatti da altri. La fatica ci fa sentire l'oggetto più nostro. L'effetto spiega perché difendiamo le nostre idee e perché coinvolgere gli altri li rende più motivati.",
ap:["L'effetto funziona solo se il lavoro viene completato: un mobile lasciato a metà non dà soddisfazione. Ci sono anche esempi famosi: secondo un racconto diffuso, i preparati per torte vendevano di più quando richiedevano di aggiungere un uovo fresco, perché chi cucinava sentiva di contribuire.","Puoi usarlo: coinvolgi le persone nella costruzione di un progetto e lo sosterranno di più. Ma attenzione al lato negativo: tendi a sopravvalutare le tue creazioni e a difendere idee solo perché le hai fatte tu."],
ri:[["Difesa delle proprie idee","Ti è difficile abbandonare un progetto che hai costruito."],["Coinvolgimento","Le persone sostengono ciò che hanno contribuito a creare."],["Sopravvalutazione","Pensi che il tuo lavoro valga più di quanto lo valutino gli altri."]],
es:[["Famiglia","Invece di decidere tu il menu della settimana, lo costruite insieme con i figli. Mangiano più volentieri ciò che hanno scelto e aiutato a cucinare."],["Lavoro","Un responsabile presenta un piano già pronto e trova resistenze. La volta dopo lo costruisce con il gruppo: tutti lo difendono."]],
ex:["Nel prossimo progetto di gruppo, lascia uno spazio vero perché gli altri contribuiscano.","Scegli una tua idea a cui sei molto legato e chiedi un parere sincero a una persona esterna.","Costruisci o ripara qualcosa con le tue mani e nota come lo valuti dopo."],
q:["Sto valutando questo lavoro per quanto vale o perché l'ho fatto io?","Come posso coinvolgere gli altri nella costruzione?","Il contributo che chiedo è vero o solo apparente?"],
er:"Chiedere contributi finti: le persone se ne accorgono e l'effetto svanisce.",
qz:[["Cosa mostra l'effetto IKEA?",["Gli oggetti IKEA sono migliori","Valutiamo di più ciò che abbiamo costruito noi","Non ci piace montare mobili","Gli oggetti pronti valgono di più"],1,"La fatica aumenta il valore percepito."],["Quando l'effetto IKEA non funziona?",["Quando il lavoro non viene completato","Quando l'oggetto è economico","Quando lavoriamo in gruppo","Sempre"],0,"Serve completare il lavoro per sentire il valore."]]}
);
